if (!function_exists('z2m_intent_handle') && defined('DIR_MODULES')) {
    include_once(DIR_MODULES . 'zigbee2mqtt/zigbee2mqtt.intents.php');
}
$text = '';
if (isset($phrase) && $phrase !== '') {
    $text = $phrase;
} elseif (isset($command) && $command !== '') {
    $text = $command;
} elseif (isset($details) && is_array($details) && isset($details['message'])) {
    $text = $details['message'];
}
$res = z2m_intent_handle($text);
if (function_exists('sg')) {
    sg('zigbee2mqttLastResult', $res['message']);
}
return $res;
